import {spawn} from 'node:child_process';
import {realpath} from 'node:fs/promises';
const root=process.env.UI_PLATFORM_STAGE3_PHYSICAL_ROOT,original=process.env.UI_PLATFORM_TEST_ORIGINAL_ROOT;
if(!root||!original||await realpath('.')!==await realpath(root)||await realpath(root)===await realpath(original))throw Error('PHYSICAL_ISOLATION_REQUIRED');
const start=performance.now(),samples=[],anomalies=[];let count=0,parentBackwards=0,childBackwards=0,lastWall=Date.now(),lastMono=performance.now(),futureIat=0,childAhead=0,minDelta=Infinity,maxDelta=-Infinity;
const code=`let previous=Date.now(),backwards=0;process.on('message',m=>{const receive=Date.now(),monoReceive=performance.now();if(receive<previous)backwards++;previous=receive;const send=Date.now(),date=new Date().getTime(),monoSend=performance.now();if(send<previous)backwards++;previous=send;process.send({...m,receive,send,date,monoReceive,monoSend,timeOrigin:performance.timeOrigin,backwards,pid:process.pid});});`;
const child=spawn(process.execPath,['-e',code],{cwd:process.cwd(),windowsHide:true,stdio:['ignore','ignore','pipe','ipc']});let errors='';child.stderr.on('data',b=>errors+=String(b));
try{await new Promise((resolve,reject)=>{child.once('error',reject);child.on('message',m=>{const received=Date.now(),mono=performance.now();count++;if(received<lastWall&&mono>=lastMono)parentBackwards++;lastWall=received;lastMono=mono;childBackwards=m.backwards;const delta=received-m.send;minDelta=Math.min(minDelta,delta);maxDelta=Math.max(maxDelta,delta);const event={...m,parentReceive:received,parentMonoReceive:mono,parentTimeOrigin:performance.timeOrigin,deltaMs:delta};if(delta<0)childAhead++;if(Math.floor(m.send/1000)>Math.floor(received/1000))futureIat++;if(samples.length<3)samples.push(event);if((delta<0||m.receive<m.parentSend)&&anomalies.length<12)anomalies.push(event);if(performance.now()-start>=10000||count>=200000)resolve();else send();});child.once('exit',c=>{if(c!==null&&c!==0)reject(Error('CLOCK_CHILD_EXIT '+c+' '+errors));});const send=()=>child.send({sequence:count,parentSend:Date.now(),parentMono:performance.now()});send();});
process.stdout.write(JSON.stringify({kind:'plain-node-to-plain-node',node:process.version,count,elapsedMs:performance.now()-start,parentPid:process.pid,childPid:child.pid,parentBackwards,childBackwards,childAhead,futureIat,minDeltaMs:minDelta,maxDeltaMs:maxDelta,samples,anomalies}));
}finally{const ended=new Promise(resolve=>child.once('exit',resolve));child.kill();await ended;}
